use std::fs

struct Tree {
    keys: Vec<i64>,
    lefts: Vec<i64>,
    rights: Vec<i64>,
    root: i64,
}

impl Tree {
    fn contains(self, x: i64) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                return true
            }
            if x < k {
                cur = self.lefts[cur as usize]
            } else {
                cur = self.rights[cur as usize]
            }
        }
        false
    }

    fn insert(self, x: i64) -> bool {
        if self.contains(x) {
            return false
        }
        let idx = self.keys.len() as i64
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root < 0 {
            self.root = idx
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                let l = self.lefts[cur as usize]
                if l < 0 {
                    self.lefts[cur as usize] = idx
                    return true
                }
                cur = l
            } else {
                let r = self.rights[cur as usize]
                if r < 0 {
                    self.rights[cur as usize] = idx
                    return true
                }
                cur = r
            }
        }
        true
    }

    fn set_child(self, parent: i64, left: bool, child: i64) {
        if parent < 0 {
            self.root = child
        } else if left {
            self.lefts[parent as usize] = child
        } else {
            self.rights[parent as usize] = child
        }
    }

    fn delete(self, x: i64) -> bool {
        let mut parent = -1
        let mut is_left = false
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                break
            }
            parent = cur
            if x < k {
                is_left = true
                cur = self.lefts[cur as usize]
            } else {
                is_left = false
                cur = self.rights[cur as usize]
            }
        }
        if cur < 0 {
            return false
        }
        let l = self.lefts[cur as usize]
        let r = self.rights[cur as usize]
        if l < 0 {
            self.set_child(parent, is_left, r)
        } else if r < 0 {
            self.set_child(parent, is_left, l)
        } else {
            let mut sp = cur
            let mut s = r
            while self.lefts[s as usize] >= 0 {
                sp = s
                s = self.lefts[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.rights[s as usize]
            if sp == cur {
                self.rights[cur as usize] = sr
            } else {
                self.lefts[sp as usize] = sr
            }
        }
        true
    }

    fn height_of(self, n: i64) -> i64 {
        if n < 0 {
            return 0
        }
        let a = self.height_of(self.lefts[n as usize])
        let b = self.height_of(self.rights[n as usize])
        if a > b {
            return a + 1
        }
        b + 1
    }

    fn inorder(self) -> string {
        let mut out = ""
        let mut stack: Vec<i64> = Vec::new()
        let mut cur = self.root
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.lefts[cur as usize]
            }
            let n = stack.pop() ?? 0
            if out.len() > 0 {
                out = out + " "
            }
            out = out + self.keys[n as usize].to_string()
            cur = self.rights[n as usize]
        }
        out
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: Vec::new(), lefts: Vec::new(), rights: Vec::new(), root: -1 }
    for line in text.lines() {
        let parts = line.split_whitespace().collect::<Vec<_>>()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x = parts[1].parse::<i64>() ?? 0
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x = parts[1].parse::<i64>() ?? 0
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x = parts[1].parse::<i64>() ?? 0
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            if t.root < 0 { println("<empty>") } else { println(t.inorder()) }
        } else if cmd == "height" {
            println(t.height_of(t.root).to_string())
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                if cmd == "min" {
                    while t.lefts[c as usize] >= 0 { c = t.lefts[c as usize] }
                } else {
                    while t.rights[c as usize] >= 0 { c = t.rights[c as usize] }
                }
                println(t.keys[c as usize].to_string())
            }
        }
    }
}

